        "³": {"item": "ds-robot-pod", "props": {"dir": "s"}},
        "µ": {"enemy": "ds-concierge", "props": {"faction": "dormant"}, "tag": "podBots"},
        "¶": {"enemy": "ds-sentinel", "props": {"faction": "dormant"}, "tag": "podBots"},
        "·": {"item": "ds-robot-pod", "props": {"dir": "w", "empty": true}},
        "¹": {"item": "ds-parts-rack", "props": {"dir": "e"}},
        "º": {"item": "ds-console", "props": {"dir": "s", "title": "Pod roster", "kicker": "The Robot Chambers", "text": "CONCIERGE 1–4 · RECEPTION · ACTIVE\nCONCIERGE 5–6 · CHARGING\nPRAETORIAN 1–2 · POSTED (BOARDROOM)\nPRAETORIAN 3 · POD EMPTY · DEPLOYED 02:14 (5A)\n\nG. MOSS: master key, security lockbox, pod 3."}},
        "»": {"item": "ds-brass-key", "props": {"name": "Mr Moss’s key", "flag": "mossKey", "desc": "His office, and his stair up to Floor 5a.", "color": "#c9a046"}},
        "¼": {"item": "ds-viewing-chair", "props": {"dir": "s", "text": "A private box, two seats. On the arm of this one, a little brass plate: RESERVED · G. MOSS. Below the glass, the Run’s steel corridors, and the Cage Lab, its cages open."}},
        "½": {"item": "ds-champagne", "props": {"title": "Champagne", "kicker": "The Private Box", "text": "A bottle in a bucket of water that was ice. Two glasses, one of them used. A note on the bucket: “For the final round. — G.M.”"}},
        "¾": {"tag": "boxZone"},
        "¿": {"enemy": "ds-board-turret", "tag": "railGun"},
        "À": {"enemy": "ds-praetorian", "props": {"face": 3.14159}, "tag": "praetorian"},
        "Á": {"item": "ds-board-eye", "props": {"face": "w"}},
        "Â": {"item": "ds-body", "props": {"title": "A Concierge", "kicker": "The Approach", "angle": 0.2, "color": "#0c0c0e", "skin": "#f4efe6", "hair": "#1a1a1a", "text": "One of the reception androids, in pieces on the steel. Its porcelain face is shot through, twice, very precisely. Whatever it was coming here to do, the guns didn’t let it."}},
        "Ã": {"tag": "approachZone"},
        "Ä": {"tag": "approachDeep"},
        "Å": {"item": "ds-board-table", "props": {"w": 6, "h": 4}},
        "Æ": {"item": "ds-board-chair", "props": {"dir": "e"}},
        "Ç": {"item": "ds-board-chair", "props": {"dir": "w"}},
        "È": {"item": "ds-secretary-desk", "props": {"dir": "s", "title": "The secretary’s desk", "kicker": "I. Brandt · Chief Science Officer", "text": "An appointment book. Every evening this month: “Nursery, 23:00 (Dr B. + S-12).” S-12 is underlined, and in the margin someone has drawn a pram with a lot of legs."}},
        "É": {"item": "ds-chesterfield", "props": {"w": 2, "dir": "n", "color": "#2a2a4a"}},
        "Ê": {"item": "ds-office-sign", "props": {"face": "n", "title": "Nameplate", "kicker": "Dr Brandt’s Office", "text": "DR I. BRANDT\nCHIEF SCIENCE OFFICER"}},
        "Ë": {"item": "ds-exec-desk", "props": {"dir": "n", "title": "Specimen S-12", "kicker": "I. Brandt · Chief Science Officer", "text": "S-12 (“THE SWADDLER”). Source: I. Brandt, REM cycles 2–6.\n\nWeaves continuously. Wraps living tissue for later use; the wrapped remain viable for days. Keeps its clutch warm.\n\nWEAKNESS: the silk is very flammable, and so, we found out the hard way, is S-12. Do not bring a lighter into the nursery."}},
        "Ì": {"item": "ds-club-chair", "props": {"dir": "w", "color": "#2a2a4a"}},
        "Í": {"item": "ds-bookcase", "props": {"dir": "w", "text": "Embryology, obstetrics, a children’s encyclopaedia of spiders with a bookmark at the page on the ones that carry their young."}},
        "Î": {"item": "ds-trauma-kit"},
        "Ï": {"item": "ds-secretary-desk", "props": {"dir": "s", "title": "The secretary’s desk", "kicker": "G. Moss · Head of Security", "text": "There is no secretary. There’s a desk, and a sign on it that says the office is staffed by appointment, and the appointments book is a list of names with times beside them and the word COLLECTED."}},
        "Ð": {"item": "ds-chesterfield", "props": {"w": 2, "dir": "n", "color": "#3a3a3e"}},
        "Ñ": {"item": "ds-office-sign", "props": {"face": "n", "title": "Nameplate", "kicker": "Mr Moss’s Office", "text": "G. MOSS\nHEAD OF SECURITY"}},
        "Ò": {"item": "ds-exec-desk", "props": {"dir": "n", "title": "Moss’s desk", "kicker": "G. Moss · Head of Security", "text": "A note on top of a stack of incident reports: “Praetorians answer to the boardroom panel only. Not to me. Not to anyone outside the room. The board wanted it that way, and I signed it, and now I’m out here. — G.”"}},
        "Ó": {"item": "weapon-rack", "props": {"weapon": "ds-riot-shotgun"}},
        "Ô": {"item": "ds-fragment", "props": {"n": 7, "title": "In the gun safe"}},
        "Õ": {"item": "ammo-shells", "props": {"amount": 16}},
        "Ö": {"item": "ammo-rockets"},
        "×": {"item": "ds-club-chair", "props": {"dir": "e", "color": "#3a3a3e"}},
        "Ø": {"enemy": "ds-gorgon", "tag": "gorgon"},
        "Ù": {"tag": "gorgonSpot"},
        "Ú": {"item": "ds-statue", "props": {"kind": "minotaur", "title": "A plaque", "kicker": "The Statue Hall", "text": "ASTERION\n\nThe Director’s own gift to the board, cast from his description. A man with a bull’s head, a double axe over his shoulder: the company’s namesake, and the monster in the middle of the maze.\n\nThe plaque goes on, in smaller letters: “There is only one story about this company worth reading. Ask him which.”"}},
        "Û": {"item": "ds-statue", "props": {"kind": "hydra", "title": "A plaque", "kicker": "The Statue Hall", "text": "THE HYDRA\n\nCut one head off and two grow back. A gift from M. Thale, “in recognition of the board’s approach to liability.”"}},
        "Ü": {"item": "ds-statue", "props": {"kind": "sphinx", "title": "A plaque", "kicker": "The Statue Hall", "text": "THE SPHINX\n\nShe asked travellers a riddle and ate the ones who got it wrong. The plaque leaves the riddle off. Someone has scratched underneath: THE ANSWER IS ALWAYS US."}},
        "Ý": {"item": "ds-statue", "props": {"kind": "cerberus", "title": "A plaque", "kicker": "The Statue Hall", "text": "CERBERUS\n\nThe dog at the gate of the dead, with three heads, so that it never sleeps. A gift from G. Moss."}},
        "Þ": {"item": "ds-note", "props": {"title": "A guide’s card", "kicker": "The Statue Hall", "text": "THE BOARD’S COLLECTION\nGuests are asked not to touch the bronzes, and on no account to look the Medusa in the eye. It is a joke, and it is also a rule."}},
        "ß": {"tag": "statueZone"},
        "à": {"item": "ds-fountain", "props": {"w": 6, "title": "The inscription", "kicker": "The Rotunda", "text": "ANDROMEDA AND CETUS\n\nChained to a rock for the sea monster, for the sake of her mother’s pride. A hero came for her, in the old story.\n\nIn this one, there is no hero in the fountain. Just her, and the thing coming up out of the water, and the water going round."}},
        "á": {"enemy": "ds-scylla", "tag": "scylla"},
        "â": {"item": "ds-charybdis", "props": {"w": 4, "on": 7, "off": 4}},
        "ã": {"tag": "rotundaZone"},
        "ä": {"item": "ds-body", "props": {"title": "A Patron", "kicker": "The Rotunda", "angle": 0.8, "color": "#2a0e12", "skin": "#f4efe6", "hair": "#1a1a1a", "text": "One of the guests, in what was evening dress, wrapped round the plinth of the dog-headed statue as though it had been flung there. The mask is cracked across. Under it there’s no face at all, only a mouth, upright, still open."}},
        "å": {"item": "ds-billiards"},
        "æ": {"item": "ds-humidor", "props": {"dir": "w", "text": "Cigars, and a ledger of who smoked which, and when, and after what. The entries are all on trial nights."}},
        "ç": {"item": "ds-club-chair", "props": {"dir": "n", "color": "#4a1416"}},
        "è": {"enemy": "ds-patron", "tag": "smokers"},
        "é": {"item": "ds-globe-bar", "props": {"title": "The globe", "kicker": "The Smoking Room", "text": "A bar, inside a globe. The decanters are labelled not with what’s in them, but with years. The oldest is older than the building."}},
        "ê": {"item": "ds-chandelier", "props": {"radius": 180, "intensity": 0.3}},
